-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     'S' AS \"LOC TYPE\",     s.STORE AS \"RMS LOCATION ID\",     s.STORE_NAME AS \"LOCATION NAME\",     s.STORE_TYPE AS \"STORE TYPE\",     CASE s.STORE_TYPE WHEN 'C' THEN 'Company' WHEN 'F' THEN 'Franchise' END                                                           AS \"STORE TYPE DESC\",      s.STORE_FORMAT AS \"STORE FORMAT\",     s.FAX_NUMBER AS \"FAX NUMBER\",     s.PHONE_NUMBER AS \"PHONE NUMBER\",     s.CURRENCY_CODE AS \"CURRENCY CODE\",     s.DEFAULT_WH AS \"DEFAULT WAREHOUSE\",     s.DISTRICT AS \"DISTRICT ID\",     s.CHANNEL_ID AS \"CHANNEL ID\",     s.STOCKHOLDING_IND AS \"STOCKHOLDING IND\",     s.LANG AS LANGUAGE_CODE,     a.ADD_1                                               AS \"ADDRESS LINE 1\",     a.ADD_2                                               AS \"ADDRESS LINE 2\",     a.CITY                                                AS \"CITY\",     a.STATE                                               AS \"STATE\",     a.POST                                                AS \"POSTCODE\",     a.COUNTRY_ID                                          AS \"COUNTRY CODE\",     s.STORE_OPEN_DATE AS \"STORE OPEN DATE\",     s.STORE_CLOSE_DATE AS \"STORE CLOSE DATE\" FROM MFCS_RDS.RDS_WV_STORE s, MFCS_RDS.RDS_WV_ADDR a  WHERE s.STORE = a.KEY_VALUE_1 and a.ADDR_TYPE = '02' and a.module='ST' and a.PRIMARY_ADDR_IND = 'Y'  UNION ALL

-- ── Query 2 ────────────────────────────────────────────────────────────
